operation.add:
{% if price_match %}
<div class="price-match-wrapper" style="margin-top:10px;">
  <a href="javascript:void(0);"
     class="btn btn-default btn-sm"
     id="button-price-match"
     data-toggle="modal"
     data-target="#modal-price-match"
     data-url="{{ price_match_url }}">
    <i class="fa fa-tags"></i> {{ text_price_match }}
  </a>
</div>

<!-- Price Match Modal -->
<div id="modal-price-match" class="modal fade" tabindex="-1" role="dialog" aria-labelledby="modal-price-match-label">
  <div class="modal-dialog" role="document">
    <div class="modal-content">
      <div class="modal-header">
        <button type="button" class="close" data-dismiss="modal" aria-label="Close"><span aria-hidden="true">&times;</span></button>
        <h4 class="modal-title" id="modal-price-match-label">{{ text_price_match }}</h4>
      </div>
      <div class="modal-body" id="modal-price-match-body">
        <div class="text-center"><i class="fa fa-spinner fa-spin fa-2x"></i></div>
      </div>
    </div>
  </div>
</div>

<script type="text/javascript">
$('#button-price-match').on('click', function() {
    var url = $(this).data('url');
    $.ajax({
        url:      url,
        type:     'GET',
        dataType: 'json',
        success: function(json) {
            if (json['html']) {
                $('#modal-price-match-body').html(json['html']);
            }
        }
    });
});
</script>
{% endif %}
